const now = new Date();
const start = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 1, 1));
const end = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 0));
const ymd = (d) => d.toISOString().slice(0, 10);

return [{
  json: {
    start_date: ymd(start),
    end_date: ymd(end),
  },
}];

function collect(nodeName) {
  const items = $(nodeName).all().map((i) => i.json);
  if (items.length === 1 && Array.isArray(items[0])) return items[0];
  return items.filter((x) => x && typeof x === 'object' && !Array.isArray(x));
}

const period = $('Prepare Last Month').first().json;
const groups = collect('Get Connector Groups');
const connectors = collect('Get Connectors');

const groupsById = Object.fromEntries(
  groups.map((g) => [String(g.id), g]),
);

const catalog = connectors.map((c) => {
  const groupId = c.connector_group_id ?? c.company_id;
  const group = groupsById[String(groupId)] || {};
  return {
    connector_id: c.id,
    username: c.username || '',
    carrier: c.carrier || '',
    carrier_display_name: c.carrier_display_name || c.carrier || '',
    enabled: c.enabled,
    status: c.status || '',
    connector_group_id: groupId,
    connector_group_name:
      group.display_name ||
      group.name ||
      c.connector_group_name ||
      c.company_name ||
      '',
  };
});

return [{
  json: {
    start_date: period.start_date,
    end_date: period.end_date,
    catalog,
  },
}];

const catalog = $('Build Catalog').first().json;
const response = $input.first().json;
let invoices = Array.isArray(response.invoices)
  ? response.invoices
  : Array.isArray(response)
    ? response
    : [];

// Shared search endpoints still return legacy field names.
const seen = new Set();
invoices = invoices.filter((inv) => {
  const connectorId = inv.connector_id ?? inv.credential_id;
  const key = [connectorId, inv.invoice_number, inv.invoice_date].join('|');
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

const rows = new Map();
for (const c of catalog.catalog || []) {
  rows.set(String(c.connector_id), {
    start_date: catalog.start_date,
    end_date: catalog.end_date,
    connector_group_id: c.connector_group_id ?? '',
    connector_group_name: c.connector_group_name || '',
    connector_id: c.connector_id,
    username: c.username || '',
    carrier: c.carrier_display_name || c.carrier || '',
    enabled: c.enabled,
    status: c.status || '',
    invoice_count: 0,
    invoice_gross_amount: 0,
    invoice_net_amount: 0,
  });
}

for (const inv of invoices) {
  const connectorId = inv.connector_id ?? inv.credential_id;
  const groupId = inv.connector_group_id ?? inv.company_id;
  const key = String(connectorId);

  if (!rows.has(key)) {
    rows.set(key, {
      start_date: catalog.start_date,
      end_date: catalog.end_date,
      connector_group_id: groupId ?? '',
      connector_group_name: '',
      connector_id: connectorId,
      username: '',
      carrier: inv.carrier || '',
      enabled: '',
      status: '',
      invoice_count: 0,
      invoice_gross_amount: 0,
      invoice_net_amount: 0,
    });
  }

  const row = rows.get(key);
  row.invoice_count += 1;
  row.invoice_gross_amount += Number(inv.invoice_gross_amount) || 0;
  row.invoice_net_amount += Number(inv.invoice_net_amount) || 0;

  if (!row.connector_group_id && groupId != null) {
    row.connector_group_id = groupId;
  }
  if (!row.carrier && inv.carrier) {
    row.carrier = inv.carrier;
  }
}

return [...rows.values()]
  .sort((a, b) => {
    const groupCmp = String(a.connector_group_name).localeCompare(
      String(b.connector_group_name),
    );
    if (groupCmp !== 0) return groupCmp;
    return b.invoice_count - a.invoice_count;
  })
  .map((row) => ({
    json: {
      ...row,
      invoice_gross_amount: Number(row.invoice_gross_amount.toFixed(2)),
      invoice_net_amount: Number(row.invoice_net_amount.toFixed(2)),
    },
  }));
